Theorem xfuzz_ubsan_put : forall (HC : HeapCeil) (H : hsr),
  heap_sr_hyps H -> (forall s LB m, hs_RHEAP H s LB m -> CanaryReads m) -> (forall MX CX, put_stmt H MX CX) -> fuzz_stmt2 H.
